pub const REPLACEMENT_CODEPOINT: u32 = 0xFFFD;

/// Finds the advance and outline slice for `cp` if mapped in the face tables.
#[inline]
pub fn lookup_glyph(cp: u32) -> Option<(u16, &'static [u8])> {
    if cp >= FIRST_CHAR as u32 && cp <= LAST_CHAR as u32 {
        let idx = (cp - FIRST_CHAR as u32) as usize;
        let start = OUTLINE_OFFSET[idx] as usize;
        let end = OUTLINE_OFFSET[idx + 1] as usize;
        let adv = ADVANCE[idx];
        return Some((adv, &OUTLINE_BYTES[start..end]));
    }
    if cp >= LATIN1_FIRST && cp <= LATIN1_LAST {
        let idx = (cp - LATIN1_FIRST) as usize;
        let start = OUTLINE_OFFSET_LATIN1[idx] as usize;
        let end = OUTLINE_OFFSET_LATIN1[idx + 1] as usize;
        let adv = ADVANCE_LATIN1[idx];
        return Some((adv, &OUTLINE_BYTES_LATIN1[start..end]));
    }
    if cp >= EXTA_FIRST && cp <= EXTA_LAST {
        let idx = (cp - EXTA_FIRST) as usize;
        let start = OUTLINE_OFFSET_EXTA[idx] as usize;
        let end = OUTLINE_OFFSET_EXTA[idx + 1] as usize;
        let adv = ADVANCE_EXTA[idx];
        return Some((adv, &OUTLINE_BYTES_EXTA[start..end]));
    }
    if let Ok(idx) = SYMBOL_CODEPOINTS.binary_search(&cp) {
        let start = OUTLINE_OFFSET_SYMBOLS[idx] as usize;
        let end = OUTLINE_OFFSET_SYMBOLS[idx + 1] as usize;
        let adv = ADVANCE_SYMBOLS[idx];
        return Some((adv, &OUTLINE_BYTES_SYMBOLS[start..end]));
    }
    None
}

/// Returns the advance and outline slice for the replacement character `U+FFFD`.
#[inline]
pub fn fallback_glyph() -> (u16, &'static [u8]) {
    let idx = SYMBOL_CODEPOINTS.len() - 1; // 0xFFFD is the last entry in SYMBOL_CODEPOINTS
    let start = OUTLINE_OFFSET_SYMBOLS[idx] as usize;
    let end = OUTLINE_OFFSET_SYMBOLS[idx + 1] as usize;
    let adv = ADVANCE_SYMBOLS[idx];
    (adv, &OUTLINE_BYTES_SYMBOLS[start..end])
}

/// Finds the advance and outline slice for `cp`, or falls back to `U+FFFD`.
#[inline]
pub fn lookup_glyph_or_fallback(cp: u32) -> (u16, &'static [u8]) {
    match lookup_glyph(cp) {
        Some(res) => res,
        None => fallback_glyph(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ascii_letters_and_symbols_resolve() {
        let (adv_a, blob_a) = lookup_glyph(b'A' as u32).expect("A exists");
        assert!(adv_a > 0);
        assert!(!blob_a.is_empty());
        assert_eq!(blob_a[0], 2, "A has 2 contours");

        let (adv_sp, blob_sp) = lookup_glyph(b' ' as u32).expect("space exists");
        assert!(adv_sp > 0);
        assert_eq!(blob_sp.len(), 1);
        assert_eq!(blob_sp[0], 0, "space has 0 contours");
    }

    #[test]
    fn latin1_accented_characters_resolve() {
        // Test common accented characters: À (0xC0), é (0xE9), ñ (0xF1), ç (0xE7), ß (0xDF), ° (0xB0)
        let chars = [
            (0x00C0, "À"),
            (0x00E9, "é"),
            (0x00F1, "ñ"),
            (0x00E7, "ç"),
            (0x00DF, "ß"),
            (0x00B0, "°"),
        ];
        for (cp, name) in chars {
            let (adv, blob) = lookup_glyph(cp).unwrap_or_else(|| panic!("missing {name} (0x{cp:04X})"));
            assert!(adv > 0, "advance for {name} should be > 0");
            assert!(!blob.is_empty(), "blob for {name} should not be empty");
            assert!(blob[0] > 0, "contour count for {name} should be > 0");
        }
    }

    #[test]
    fn latin_extended_a_characters_resolve() {
        // Test Latin Extended-A characters: Ā (0x100), č (0x10D), š (0x161), ž (0x17E)
        let chars = [
            (0x0100, "Ā"),
            (0x010D, "č"),
            (0x0161, "š"),
            (0x017E, "ž"),
        ];
        for (cp, name) in chars {
            let (adv, blob) = lookup_glyph(cp).unwrap_or_else(|| panic!("missing {name} (0x{cp:04X})"));
            assert!(adv > 0, "advance for {name} should be > 0");
            assert!(!blob.is_empty(), "blob for {name} should not be empty");
            assert!(blob[0] > 0, "contour count for {name} should be > 0");
        }
    }

    #[test]
    fn typographical_symbols_resolve() {
        // Em-dash, en-dash, smart quotes, bullet, ellipsis, euro
        let symbols = [
            (0x2013, "en-dash"),
            (0x2014, "em-dash"),
            (0x2018, "left single quote"),
            (0x2019, "right single quote"),
            (0x201C, "left double quote"),
            (0x201D, "right double quote"),
            (0x2022, "bullet"),
            (0x2026, "ellipsis"),
            (0x20AC, "euro"),
        ];
        for (cp, name) in symbols {
            let (adv, blob) = lookup_glyph(cp).unwrap_or_else(|| panic!("missing {name} (0x{cp:04X})"));
            assert!(adv > 0, "advance for {name} should be > 0");
            assert!(!blob.is_empty(), "blob for {name} should not be empty");
            assert!(blob[0] > 0, "contour count for {name} should be > 0");
        }
    }

    #[test]
    fn fallback_glyph_resolves_and_has_ink() {
        let (adv_fb, blob_fb) = fallback_glyph();
        assert!(adv_fb > 0);
        assert!(!blob_fb.is_empty());
        assert!(blob_fb[0] > 0, "fallback glyph should have contours");

        // Unmapped codepoint should return None from lookup_glyph
        assert!(lookup_glyph(0x1F600).is_none());
        assert!(lookup_glyph(0x4E00).is_none());

        // But lookup_glyph_or_fallback should return the fallback glyph
        let (adv_fb2, blob_fb2) = lookup_glyph_or_fallback(0x1F600);
        assert_eq!(adv_fb2, adv_fb);
        assert_eq!(blob_fb2, blob_fb);
    }
}
